 private void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(16);t.setPadding(8,8,8,8);controls.addView(t);}private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setMinHeight(54);b.setOnClickListener(v->{try{r.run();}catch(Exception e){say("No se pudo completar la acción.");}});controls.addView(b);}
 private CheckBox check(String s,boolean on,Runnable r){CheckBox b=new CheckBox(this);b.setText(s);b.setChecked(on);b.setOnCheckedChangeListener((v,checked)->r.run());controls.addView(b);return b;}
 private EditText edit(String label,String value,boolean password){text(label);EditText e=new EditText(this);e.setContentDescription(label);e.setSingleLine(true);e.setText(value);if(password)e.setInputType(129);e.setSaveEnabled(false);controls.addView(e);return e;}
 private Spinner select(String name,String[] values,java.util.function.IntConsumer action){text(name);Spinner s=new Spinner(this);s.setContentDescription(name);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){action.accept(n);}});controls.addView(s);return s;}
 private String overview(){return (interpretations.isChecked()?scene.source+". Interpretación aproximada: "+scene.overview+" ":"Interpretaciones ocultas. ")+scene.regions.size()+" regiones explorables. "+Orientation.overview(extracted.geometry);}
 private String description(){if(scene.regions.isEmpty())return "Todavía no hay componentes.";int n=Math.min(selected,scene.regions.size()-1);return "Componente "+(n+1)+". "+scene.regions.get(n).description(interpretations.isChecked())+(focused>=0?" Estás en una vista ampliada; los sonidos ahora expresan posiciones dentro de esta región.":"");}
 private void refresh(){if(choices==null)return;int n=Math.min(selected,scene.regions.size()-1);String[] names=new String[scene.regions.size()];for(int i=0;i<names.length;i++)names[i]=(i+1)+". "+(interpretations.isChecked()?scene.regions.get(i).label:"Región geométrica");choices.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));selected=Math.max(0,n);choices.setSelection(selected);canvas.invalidate();}
 private void focus(int n){if(n<0||n>=scene.regions.size())return;stop();selected=n;focused=n;ImageScene.Region r=scene.regions.get(n);geometry=ImageScene.focus(extracted.geometry,r,extracted.left,extracted.top,extracted.width*extracted.scale,extracted.height*extracted.scale);canvas.point=new Geometry.Point(300,225);canvas.map.reset();canvas.invalidate();speak("Primer plano. "+description(),null);}
 private void restore(){stop();focused=-1;geometry=extracted.geometry;canvas.map.reset();canvas.invalidate();speak("Vista general restaurada. La imagen conserva su posición original.",null);}
 private void correct(){if(scene.regions.isEmpty())return;ImageScene.Region r=scene.regions.get(Math.min(selected,scene.regions.size()-1));LinearLayout form=new LinearLayout(this);form.setOrientation(1);EditText label=new EditText(this),like=new EditText(this);label.setHint("Tu interpretación");label.setContentDescription("Tu interpretación");label.setText(r.label);like.setHint("Analogía opcional");like.setContentDescription("Analogía opcional");like.setText(r.analogy);label.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});like.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(240)});form.addView(label);form.addView(like);new AlertDialog.Builder(this).setTitle("Anotación para esta captura").setView(form).setPositiveButton("Guardar",(d,w)->{epoch++;busy=false;r.label=ImageScene.clean(label.getText(),160);r.analogy=ImageScene.clean(like.getText(),240);r.source="Anotación del usuario";refresh();say("Anotación guardada para esta captura. No modifica el contorno ni entrena el modelo.");}).setNegativeButton("Cancelar",null).show();}
 private void analyze(boolean remote){if(busy)return;if(remote&&engine<2){say("Elige Gemini o API compatible antes de enviar.");return;}if(!remote&&engine>=2){say("Elige uno de los dos motores locales.");return;}stop();busy=true;final int request=++epoch,chosen=engine;final String url=endpoint.getText().toString().trim(),name=model.getText().toString().trim(),secret=key.getText().toString();if(remote&&name.isEmpty()){busy=false;say("Indica el modelo de visión habilitado en tu proveedor.");return;}final Bitmap snapshot=image.copy(Bitmap.Config.ARGB_8888,false);say(remote?"Consultando la API elegida…":"Reconociendo localmente; la imagen no sale del dispositivo…");worker.execute(()->{try{ImageScene result;if(remote){ByteArrayOutputStream out=new ByteArrayOutputStream();snapshot.compress(Bitmap.CompressFormat.PNG,100,out);result=VisionApi.analyze(out.toByteArray(),chosen==2?"gemini":"compatible",url,name,secret);}else result=LocalVision.analyze(this,snapshot,chosen==1);main.post(()->{if(closed||request!=epoch)return;busy=false;focused=-1;selected=0;geometry=extracted.geometry;scene=result;scene.addUnknown(geometry,extracted.left,extracted.top,extracted.width*extracted.scale,extracted.height*extracted.scale);refresh();if(active)speak(overview(),null);else say(overview());});}catch(Throwable e){main.post(()->{if(!closed&&request==epoch){busy=false;say(remote?"La API no pudo analizar la imagen. Revisa dirección, modelo, clave y conexión. Los contornos siguen disponibles.":"El motor local no pudo ejecutarse en este equipo. Los componentes geométricos siguen disponibles; puedes probar el otro motor.");}});}finally{snapshot.recycle();}});}
 private void say(String s){status.setText(s);}private void speak(String s,Runnable then){stop();say(s);if(active&&narration.isChecked()&&voiceReady){afterVoice=then;pendingSpeech=UUID.randomUUID().toString();voice.speak(s,TextToSpeech.QUEUE_FLUSH,null,pendingSpeech);}else if(then!=null)then.run();}private void stop(){pendingSpeech="";if(audio!=null)audio.stop();if(voice!=null)voice.stop();afterVoice=null;}
 private final class ExplorerCanvas extends View {
  final Paint paint=new Paint(3);final TouchMap map=new TouchMap();Geometry.Point point=new Geometry.Point(300,225);final GestureDetector gestures;boolean openedInGesture;
  ExplorerCanvas(){super(ImageExplorerActivity.this);setFocusable(true);setContentDescription("Lienzo de componentes. Doble toque abre la región señalada. También puedes usar la lista y el botón Abrir componente.");setClickable(true);gestures=new GestureDetector(ImageExplorerActivity.this,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(android.view.MotionEvent e){return true;}public boolean onDoubleTap(android.view.MotionEvent e){openedInGesture=true;openPoint();return true;}});}
  protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(0xff15232b);float s=Math.min(getWidth()/600f,getHeight()/450f);c.save();c.translate((getWidth()-600*s)/2,(getHeight()-450*s)/2);c.scale(s,s);Rect src=new Rect(0,0,image.getWidth(),image.getHeight());RectF dest=new RectF((float)extracted.left,(float)extracted.top,(float)(extracted.left+extracted.width*extracted.scale),(float)(extracted.top+extracted.height*extracted.scale));if(focused>=0){ImageScene.Region r=scene.regions.get(focused);src=new Rect((int)(r.left*image.getWidth()),(int)(r.top*image.getHeight()),Math.max((int)(r.left*image.getWidth())+1,(int)Math.ceil(r.right*image.getWidth())),Math.max((int)(r.top*image.getHeight())+1,(int)Math.ceil(r.bottom*image.getHeight())));double w=(r.right-r.left)*extracted.width*extracted.scale,h=(r.bottom-r.top)*extracted.height*extracted.scale,z=Math.min(568/w,418/h);dest=new RectF((float)((600-w*z)/2),(float)((450-h*z)/2),(float)((600+w*z)/2),(float)((450+h*z)/2));}paint.setAlpha(150);c.drawBitmap(image,src,dest,paint);paint.setAlpha(255);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2);paint.setColor(0xffdbed9c);for(Geometry.Shape shape:geometry.shapes){Path p=new Path();for(int i=0;i<shape.points.size();i++){Geometry.Point q=shape.points.get(i);if(i==0)p.moveTo((float)q.x,(float)q.y);else p.lineTo((float)q.x,(float)q.y);}if(shape.closed)p.close();c.drawPath(p,paint);}if(focused<0){paint.setColor(0xffffb75c);for(ImageScene.Region r:scene.regions)c.drawRect((float)(extracted.left+r.left*extracted.width*extracted.scale),(float)(extracted.top+r.top*extracted.height*extracted.scale),(float)(extracted.left+r.right*extracted.width*extracted.scale),(float)(extracted.top+r.bottom*extracted.height*extracted.scale),paint);}c.restore();}
  void sample(float x,float y){float s=Math.min(getWidth()/600f,getHeight()/450f);if(s<=0)return;point=new Geometry.Point((x-(getWidth()-600*s)/2)/s,(y-(getHeight()-450*s)/2)/s);TouchMap.Feedback f=map.sample(geometry,point,0,0,18,true);if(f.kind.equals("silent"))audio.stop();else audio.touch(f.position,f.kind);}
  void openPoint(){if(focused>=0)return;double x=(point.x-extracted.left)/(extracted.width*extracted.scale),y=(point.y-extracted.top)/(extracted.height*extracted.scale);int best=-1;double area=2;for(int i=0;i<scene.regions.size();i++){ImageScene.Region r=scene.regions.get(i);double a=(r.right-r.left)*(r.bottom-r.top);if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom&&a<area){area=a;best=i;}}if(best>=0)focus(best);else say("No hay región delimitada en esa posición. Usa la lista para elegir otra.");}
  public boolean onTouchEvent(android.view.MotionEvent e){openedInGesture=false;if(e.getActionMasked()==MotionEvent.ACTION_DOWN){stop();map.reset();}gestures.onTouchEvent(e);if(openedInGesture)return true;if(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE)sample(e.getX(),e.getY());if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)audio.stop();return true;}
  public boolean onHoverEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_HOVER_ENTER||e.getActionMasked()==MotionEvent.ACTION_HOVER_MOVE)sample(e.getX(),e.getY());if(e.getActionMasked()==MotionEvent.ACTION_HOVER_EXIT)audio.stop();return true;}
  public boolean performClick(){super.performClick();openPoint();return true;}
 }
 @Override public void onBackPressed(){if(focused>=0)restore();else super.onBackPressed();}
 @Override protected void onResume(){super.onResume();active=true;} @Override protected void onPause(){active=false;super.onPause();stop();}
 @Override protected void onDestroy(){closed=true;epoch++;if(isFinishing()&&snapshotName!=null)deleteFile(snapshotName);worker.shutdownNow();stop();if(audio!=null)audio.close();if(voice!=null)voice.shutdown();super.onDestroy();}
